import { PUBLIC_API_URL } from "$env/static/public";
import { Constants, HTTP } from "$lib";
import { authenticatedMutation, type MutationIntent } from "$platform/authenticated-mutation";

export interface SearchReportRequest {
	category?: string;
	object?: string;
	reason?: string;
	status?: string;
	order?: "asc" | "desc";
}

export const Search = (searchParams: URLSearchParams) => {
	const http = new HTTP<ReportFeedResponse>(`${PUBLIC_API_URL}/report${searchParams.toString()}`);
	http.setWithCredentials(true);
	return http.GET();
};

export const Reasons = (entity: Constants.EntityType) => {
	const http = new HTTP<ReportReason[]>(`${PUBLIC_API_URL}/report/reasons/${entity}`);
	return http.GET();
};

export interface CreateReportRequest {
	entity_type: Constants.EntityType;
	entity_id: string;
	reason_id: string;
	details?: string;
}

export const Create = (payload: CreateReportRequest, intent?: MutationIntent) => authenticatedMutation<void>("/report", "POST", payload, intent);
export const Delete = (id: string, intent?: MutationIntent) => authenticatedMutation<void>(`/report/${encodeURIComponent(id)}`, "DELETE", undefined, intent);
export const Accept = (id: string, notes?: string, intent?: MutationIntent) => authenticatedMutation<Report>(`/report/${encodeURIComponent(id)}/accept`, "POST", { notes }, intent);
export const Reject = (id: string, notes?: string, intent?: MutationIntent) => authenticatedMutation<Report>(`/report/${encodeURIComponent(id)}/reject`, "POST", { notes }, intent);
